INSERT INTO public.tracker_entry
  (id, quarter, sector, status, finding, detail, sources, verification, published)
VALUES
  ('geothermal-2025q1', '2025Q1', 'geothermal', 'advanced',
   'ESDM Regulation 5/2025 on renewable power purchase agreements (signed 27 February, promulgated 4 March 2025) allows the price in a geothermal pre-transaction agreement to be adjusted in light of exploration results and the ceiling price.',
   'Article 29 sets the adjustment rule, and Article 12(2) lets a geothermal plant reach commercial operation in stages as steam supply allows. The regulation sets no new ceiling: geothermal prices remain capped by Presidential Regulation 112/2022 (13 September 2022), whose Annex I gives a cent-per-kWh ceiling by plant size, multiplied by a regional location factor. On 14 January 2025 ADB signed USD 92.6 million for the 83 MW Muara Laboh expansion, including a USD 15 million concessional loan from the Australian Climate Finance Partnership.',
   '[{"title":"Peraturan Menteri ESDM Nomor 5 Tahun 2025 tentang Pedoman Perjanjian Jual Beli Tenaga Listrik dari Pembangkit Tenaga Listrik yang Memanfaatkan Sumber Energi Terbarukan","issuer":"Kementerian Energi dan Sumber Daya Mineral","doc_no":"Permen ESDM No. 5 Tahun 2025","date":"2025-02-27","url":"https://jdih.esdm.go.id/dokumen/view?id=2553","accessed":"2026-10-11"},{"title":"Percepat Pengembangan Pembangkit EBT, Kementerian ESDM Terbitkan Aturan Perjanjian Jual Beli Tenaga Listrik","issuer":"Kementerian Energi dan Sumber Daya Mineral","doc_no":"Siaran Pers 018.Pers/04/SJI/2025","date":"2025-03-11","url":"https://www.esdm.go.id/id/media-center/arsip-berita/percepat-pengembangan-pembangkit-ebt-kementerian-esdm-terbitkan-aturan-perjanjian-jual-beli-tenaga-listrik-","accessed":"2026-10-11"},{"title":"Peraturan Presiden Nomor 112 Tahun 2022 tentang Percepatan Pengembangan Energi Terbarukan untuk Penyediaan Tenaga Listrik","issuer":"Presiden Republik Indonesia","doc_no":"Perpres No. 112 Tahun 2022","date":"2022-09-13","url":"https://jdih.kemenkeu.go.id/api/download/7332a343-0623-4d26-80f2-9d8f62a5c2ba/2022perpres112.pdf","accessed":"2026-10-11"},{"title":"ADB Supports Indonesia''s Green Energy Transition with Geothermal Expansion Project","issuer":"Asian Development Bank","date":"2025-01-14","url":"https://www.adb.org/news/adb-supports-indonesia-green-energy-transition-geothermal-expansion-project","accessed":"2026-10-11"}]'::jsonb,
   'verified', false),
  ('geothermal-2025q2', '2025Q2', 'geothermal', 'mixed',
   'Muara Laboh Unit 2 (80 MW) reached financial close on 18 April 2025 at a tariff under Presidential Regulation 112/2022, and the World Bank cut its geothermal exploration facility (GREM) by 57 percent in a restructuring paper disclosed on 24 June 2025.',
   'The Coordinating Ministry for Economic Affairs dates the financial close to 18 April, and ESDM''s release of 5 May quotes the Director General for renewable energy saying units 2 and 3 are priced under Perpres 112/2022. RUPTL 2025–2034 (26 May 2025) also names Perpres 112/2022 as the basis for geothermal purchase prices and plans 5.2 GW of new geothermal capacity. On 26 June three geothermal plants totalling 91.9 MW were inaugurated as ready for commercial operation. The World Bank paper cancels USD 85 million of the USD 150 million IBRD loan, records no disbursement under the exploration component as of June 2025, and attributes the perceived bottlenecks to the facility''s financial terms and its loan-forgiveness mechanism.',
   '[{"title":"Perkuat Kerja Sama Strategis Transisi Energi Melalui Skema AZEC, Indonesia dan Jepang Tandatangani Perjanjian Perkembangan PLTP Muara Laboh","issuer":"Kementerian Koordinator Bidang Perekonomian","doc_no":"Siaran Pers HM.02.04/146/SET.M.EKON.3/05/2025","date":"2025-05-05","url":"https://www.ekon.go.id/publikasi/detail/6340/perkuat-kerja-sama-strategis-transisi-energi-melalui-skema-azec-indonesia-dan-jepang-tandatangani-perjanjian-perkembangan-pltp-muara-laboh","accessed":"2026-10-11"},{"title":"Capai Financial Close, PLTP Muara Laboh Unit 2 Ditargetkan Selesai 2027","issuer":"Kementerian Energi dan Sumber Daya Mineral","date":"2025-05-05","url":"https://www.esdm.go.id/id/media-center/arsip-berita/capai-financial-close-pltp-muara-laboh-unit-2-ditargetkan-selesai-2027","accessed":"2026-10-11"},{"title":"Keputusan Menteri ESDM Nomor 188.K/TL.03/MEM.L/2025 tentang Pengesahan Rencana Usaha Penyediaan Tenaga Listrik PT PLN (Persero) Tahun 2025 sampai dengan Tahun 2034","issuer":"Kementerian Energi dan Sumber Daya Mineral","doc_no":"Kepmen ESDM No. 188.K/TL.03/MEM.L/2025","date":"2025-05-26","url":"https://jdih.esdm.go.id/dokumen/view?id=2584","accessed":"2026-10-11"},{"title":"Presiden Prabowo dan Menteri Bahlil Resmikan 55 Proyek Energi Terbarukan dan Tambahan Produksi Minyak Blok Cepu","issuer":"Kementerian Energi dan Sumber Daya Mineral","doc_no":"Siaran Pers 059.Pers/04/SJI/2025","date":"2025-06-26","url":"https://www.esdm.go.id/id/media-center/arsip-berita/-presiden-prabowo-dan-menteri-bahlil-resmikan-55-proyek-energi-terbarukan-dan-tambahan-produksi-minyak-blok-cepu","accessed":"2026-10-11"},{"title":"Disclosable Restructuring Paper, Indonesia Geothermal Resource Risk Mitigation Project (GREM), P166071","issuer":"World Bank","doc_no":"Report No. RES00156","date":"2025-06-24","url":"https://documents.worldbank.org/curated/en/099062425200024781/pdf/P166071-df869a6a-9a2b-4758-b267-62622cc4d050.pdf","accessed":"2026-10-11"}]'::jsonb,
   'verified', false),
  ('solar-2025q1', '2025Q1', 'solar', 'unchanged',
   'Solar plants in Q1 2025 were under the local-content rules of ESDM Regulation 11/2024 (31 July 2024) and Ministerial Decision 191.K/EK.01/MEM.E/2024 (6 August 2024), which set a 20 percent minimum for solar projects.',
   'The 2024 decision lowered the minimum combined goods-and-services TKDN for solar plants to 20 percent, from 40.68–45.90 percent before. Article 19 of the regulation lets solar projects with a power purchase agreement signed by 31 December 2024 and commercial operation planned by 30 June 2026 use imported modules, with the relaxation running until 30 June 2025; otherwise imports are allowed only where the goods are not made domestically, domestic goods fall short of the specification, or domestic output cannot meet demand (Article 4). The renewable-energy directorate''s 2025 performance report records realised solar TKDN of 24.49 percent in Q1 2025 against the 20 percent target.',
   '[{"title":"Peraturan Menteri ESDM Nomor 11 Tahun 2024 tentang Penggunaan Produk Dalam Negeri untuk Pembangunan Infrastruktur Ketenagalistrikan","issuer":"Kementerian Energi dan Sumber Daya Mineral","doc_no":"Permen ESDM No. 11 Tahun 2024","date":"2024-07-30","url":"https://jdih.esdm.go.id/dokumen/view?id=2469","accessed":"2026-10-11"},{"title":"Keputusan Menteri ESDM Nomor 191.K/EK.01/MEM.E/2024 tentang Batas Minimum Nilai Tingkat Komponen Dalam Negeri Gabungan Barang dan Jasa dalam Lingkup Proyek Pembangunan Infrastruktur Ketenagalistrikan","issuer":"Kementerian Energi dan Sumber Daya Mineral","doc_no":"Kepmen ESDM No. 191.K/EK.01/MEM.E/2024","date":"2024-08-06","url":"https://docs.paralegal.id/PERMEN/PERMEN-ESDM/KEPMEN-ESDM/2024/KEPMEN-ESDM-191-K-EK-01-MEM-E-2024.pdf","accessed":"2026-10-11"},{"title":"Gelar Sosialisasi Regulasi TKDN, Sekjen ESDM: Percepat Pembangunan Infrastruktur Listrik Gunakan Produk Dalam Negeri","issuer":"Kementerian Energi dan Sumber Daya Mineral","doc_no":"Siaran Pers 446.Pers/04/SJI/2024","date":"2024-08-12","url":"https://www.esdm.go.id/id/media-center/arsip-berita/gelar-sosialisasi-regulasi-tkdn-sekjen-esdm-percepat-pembangunan-infrastruktur-listrik-gunakan-produk-dalam-negeri","accessed":"2026-10-11"},{"title":"Beri Relaksasi TKDN PLTS, Ini Batas Waktunya","issuer":"Kementerian Energi dan Sumber Daya Mineral","doc_no":"Siaran Pers 448.Pers/04/SJI/2024","date":"2024-08-13","url":"https://esdm.go.id/id/media-center/arsip-berita/beri-relaksasi-tkdn-plts-ini-batas-waktunya","accessed":"2026-10-11"},{"title":"Laporan Kinerja Direktorat Jenderal EBTKE Tahun 2025","issuer":"Direktorat Jenderal EBTKE, Kementerian ESDM","date":"2026-02-27","url":"https://www.esdm.go.id/assets/media/content/content-laporan-kinerja-ditjen-ebtke-tahun-2025.pdf","accessed":"2026-10-11"}]'::jsonb,
   'verified', false),
  ('solar-2025q2', '2025Q2', 'solar', 'mixed',
   'RUPTL 2025–2034 (26 May 2025) plans 17.1 GW of utility-scale solar, and the import relaxation for solar projects under ESDM Regulation 11/2024 ended on 30 June 2025, the date the regulation set.',
   'The 17.1 GW is the plan''s ARED scenario, 24.5 percent of planned additions; its RE Base scenario has 7.1 GW. The RUPTL itself says that under the current TKDN and purchase-price rules, adding solar and wind with batteries cannot yet replace gas-fired plants. The renewable-energy directorate''s 2025 performance report records 233.26 MW of solar added in the first half of 2025, for 1,142.69 MW installed, and realised solar TKDN of 24.49 percent in Q2.',
   '[{"title":"Keputusan Menteri ESDM Nomor 188.K/TL.03/MEM.L/2025 tentang Pengesahan Rencana Usaha Penyediaan Tenaga Listrik PT PLN (Persero) Tahun 2025 sampai dengan Tahun 2034","issuer":"Kementerian Energi dan Sumber Daya Mineral","doc_no":"Kepmen ESDM No. 188.K/TL.03/MEM.L/2025","date":"2025-05-26","url":"https://jdih.esdm.go.id/dokumen/view?id=2584","accessed":"2026-10-11"},{"title":"Peraturan Menteri ESDM Nomor 11 Tahun 2024 tentang Penggunaan Produk Dalam Negeri untuk Pembangunan Infrastruktur Ketenagalistrikan","issuer":"Kementerian Energi dan Sumber Daya Mineral","doc_no":"Permen ESDM No. 11 Tahun 2024","date":"2024-07-30","url":"https://jdih.esdm.go.id/dokumen/view?id=2469","accessed":"2026-10-11"},{"title":"Laporan Kinerja Direktorat Jenderal EBTKE Tahun 2025","issuer":"Direktorat Jenderal EBTKE, Kementerian ESDM","date":"2026-02-27","url":"https://www.esdm.go.id/assets/media/content/content-laporan-kinerja-ditjen-ebtke-tahun-2025.pdf","accessed":"2026-10-11"}]'::jsonb,
   'verified', false),
  ('pln_procurement-2025q1', '2025Q1', 'pln_procurement', 'advanced',
   'ESDM ratified the national electricity plan (RUKN, Ministerial Decision 85.K/TL.01/MEM.L/2025) on 5 March 2025, while PLN''s procurement still ran under RUPTL 2021–2030 and RUPTL 2025–2034 had not yet been issued.',
   'The RUKN projects demand rising from 539 TWh in 2025 to about 1,813 TWh in 2060 and is the reference for drafting the RUPTL. RUPTL 2021–2030 (Ministerial Decision 188.K/HK.02/MEM.L/2021) stayed in force until the 2025 decision revoked it on 26 May; that decision recites PLN''s requests for a new RUPTL dated from 31 October 2024. ESDM Regulation 5/2025, in force from 4 March 2025, set new terms for PLN''s renewable power purchase agreements, including a developer performance bond of at most 10 percent of project cost and deemed-dispatch payment when PLN curtails output.',
   '[{"title":"Keputusan Menteri ESDM Nomor 85.K/TL.01/MEM.L/2025 tentang Rencana Umum Ketenagalistrikan Nasional","issuer":"Kementerian Energi dan Sumber Daya Mineral","doc_no":"Kepmen ESDM No. 85.K/TL.01/MEM.L/2025","date":"2025-03-05","url":"https://jdih.esdm.go.id/dokumen/view?id=2561","accessed":"2026-10-11"},{"title":"Keputusan Menteri ESDM Nomor 188.K/TL.03/MEM.L/2025 tentang Pengesahan Rencana Usaha Penyediaan Tenaga Listrik PT PLN (Persero) Tahun 2025 sampai dengan Tahun 2034","issuer":"Kementerian Energi dan Sumber Daya Mineral","doc_no":"Kepmen ESDM No. 188.K/TL.03/MEM.L/2025","date":"2025-05-26","url":"https://jdih.esdm.go.id/dokumen/view?id=2584","accessed":"2026-10-11"},{"title":"Peraturan Menteri ESDM Nomor 5 Tahun 2025 tentang Pedoman Perjanjian Jual Beli Tenaga Listrik dari Pembangkit Tenaga Listrik yang Memanfaatkan Sumber Energi Terbarukan","issuer":"Kementerian Energi dan Sumber Daya Mineral","doc_no":"Permen ESDM No. 5 Tahun 2025","date":"2025-02-27","url":"https://jdih.esdm.go.id/dokumen/view?id=2553","accessed":"2026-10-11"}]'::jsonb,
   'verified', false),
  ('pln_procurement-2025q2', '2025Q2', 'pln_procurement', 'advanced',
   'ESDM ratified RUPTL 2025–2034 on 26 May 2025 (Ministerial Decision 188.K/TL.03/MEM.L/2025), planning 69.5 GW of new capacity of which 42.6 GW is renewable and 10.3 GW is storage, and published the document on 3 June 2025.',
   'The decision targets a 34.3 percent renewable share of generation by the end of 2034 and 47,758 circuit-km of new transmission, and revokes RUPTL 2021–2030. Its financing chapter says PLN''s borrowing is limited by lender and bondholder covenants, and that without added state equity or a higher margin PLN''s debt-service and debt-to-EBITDA ratios are unhealthy. Earlier in the quarter, ESDM Regulation 10/2025 (signed 10 April 2025) set the power-sector transition roadmap required by Perpres 112/2022, restating its ban on new coal plants and the exceptions to it. On 6 April 2025 the Minister ordered PLN to build 40 MW of geothermal in Maluku, saying the Tulehu 2×10 MW plant was at PLN''s procurement stage with commercial operation targeted for 2031.',
   '[{"title":"Keputusan Menteri ESDM Nomor 188.K/TL.03/MEM.L/2025 tentang Pengesahan Rencana Usaha Penyediaan Tenaga Listrik PT PLN (Persero) Tahun 2025 sampai dengan Tahun 2034","issuer":"Kementerian Energi dan Sumber Daya Mineral","doc_no":"Kepmen ESDM No. 188.K/TL.03/MEM.L/2025","date":"2025-05-26","url":"https://jdih.esdm.go.id/dokumen/view?id=2584","accessed":"2026-10-11"},{"title":"Menteri ESDM Umumkan RUPTL PLN 2025-2034, Serap Lebih dari 1,7 Juta Tenaga Kerja Baru","issuer":"Kementerian Energi dan Sumber Daya Mineral","doc_no":"Siaran Pers 046.Pers/04/SJI/2025","date":"2025-05-26","url":"https://www.esdm.go.id/id/media-center/arsip-berita/menteri-esdm-umumkan-ruptl-pln-2025-2034-serap-lebih-dari-17-juta-tenaga-kerja-baru","accessed":"2026-10-11"},{"title":"Kementerian ESDM Resmi Merilis Dokumen RUPTL PLN 2025-2034","issuer":"Kementerian Energi dan Sumber Daya Mineral","date":"2025-06-03","url":"https://www.esdm.go.id/id/media-center/arsip-berita/kementerian-esdm-resmi-merilis-dokumen-ruptl-pln-2025-2034","accessed":"2026-10-11"},{"title":"Peraturan Menteri ESDM Nomor 10 Tahun 2025 tentang Peta Jalan (Road Map) Transisi Energi Sektor Ketenagalistrikan","issuer":"Kementerian Energi dan Sumber Daya Mineral","doc_no":"Permen ESDM No. 10 Tahun 2025","date":"2025-04-10","url":"https://jdih.esdm.go.id/dokumen/view?id=2567","accessed":"2026-10-11"},{"title":"Peraturan Presiden Nomor 112 Tahun 2022 tentang Percepatan Pengembangan Energi Terbarukan untuk Penyediaan Tenaga Listrik","issuer":"Presiden Republik Indonesia","doc_no":"Perpres No. 112 Tahun 2022","date":"2022-09-13","url":"https://jdih.kemenkeu.go.id/api/download/7332a343-0623-4d26-80f2-9d8f62a5c2ba/2022perpres112.pdf","accessed":"2026-10-11"},{"title":"Maluku Butuh Energi Bersih, Menteri Bahlil Perintahkan PLN Bangun Pembangkit Panas Bumi 40 MW","issuer":"Kementerian Energi dan Sumber Daya Mineral","doc_no":"Siaran Pers 028.Pers/04/SJI/2025","date":"2025-04-06","url":"https://www.esdm.go.id/id/media-center/arsip-berita/maluku-butuh-energi-bersih-menteri-bahlil-perintahkan-pln-bangun-pembangkit-panas-bumi-40-mw","accessed":"2026-10-11"}]'::jsonb,
   'verified', false),
  ('jetp-2025q1', '2025Q1', 'jetp', 'mixed',
   'The United States left the JETP International Partners Group (recorded by South Africa''s foreign ministry on 6 March 2025), Germany took the co-lead with Japan, and the partners reported nine loan and equity investments worth USD 1.1 billion approved (21 February 2025).',
   'South Africa''s statement says the US ended its membership of the partners group for South Africa, Indonesia and Vietnam and that its financial pledges are withdrawn. Germany''s release lists one USD 1 billion guarantee signed and 43 grant-funded projects worth USD 230 million. On 24 March the Coordinating Ministry for Economic Affairs announced an energy transition and green economy task force under Kepmenko Perekonomian 141/2025 and reported 54 projects with USD 1.1 billion committed. None of these documents gives a disbursed total; they report approved, committed or signed amounts.',
   '[{"title":"South Africa notes the decision by the United States Government to withdraw from the Just Energy Transition Partnership","issuer":"Department of International Relations and Cooperation, Republic of South Africa","date":"2025-03-06","url":"https://dirco.gov.za/south-africa-notes-the-decision-by-the-united-states-government-to-withdraw-from-the-just-energy-transition-partnership/","accessed":"2026-10-11"},{"title":"Mission Statement: Germany Assumes Co-Lead of Indonesia''s Just Energy Transition Partnership (JETP)","issuer":"Federal Foreign Office (Germany), Embassy Jakarta","date":"2025-02-21","url":"https://jakarta.diplo.de/id-en/jetp-2702134","accessed":"2026-10-11"},{"title":"Perkuat Komitmen Percepatan Implementasi Just Energy Transition Partnership (JETP), Pemerintah Bentuk Satgas Transisi Energi dan Ekonomi Hijau","issuer":"Kementerian Koordinator Bidang Perekonomian","doc_no":"Siaran Pers HM.02.04/107/SET.M.EKON.3/03/2025","date":"2025-03-24","url":"https://ekon.go.id/publikasi/detail/6275/perkuat-komitmen-percepatan-implementasi-just-energy-transition-partnership-jetp-pemerintah-bentuk-satgas-transisi-energi-dan-ekonomi-hijau","accessed":"2026-10-11"}]'::jsonb,
   'verified', false),
  ('jetp-2025q2', '2025Q2', 'jetp', 'advanced',
   'Germany''s KfW and Indonesia''s Ministry of Finance signed a EUR 200 million policy-based loan on 30 June 2025, which Germany presents as part of JETP, after the Saguling floating-solar investment was signed on 29 April 2025.',
   'The loan supports the Affordable and Sustainable Energy Transition Program (ASET) and is part of a financing envelope co-financed by ADB and AFD. The Coordinating Ministry''s release of 29 April says the Saguling project, financed by DEG, Proparco and Standard Chartered, mobilises USD 60 million for JETP Indonesia. Germany''s February release called the Muara Laboh geothermal expansion the first JETP project co-funded with private finance; it reached financial close on 18 April 2025.',
   '[{"title":"Germany and Indonesia sign EUR 200 million agreement to advance the Just Energy Transition","issuer":"Federal Foreign Office (Germany), Embassy Jakarta","date":"2025-06-30","url":"https://jakarta.diplo.de/id-en/jetp-juni-2725664","accessed":"2026-10-11"},{"title":"Implementasi Just Energy Transition Partnership (JETP) Melalui Pengembangan Pembangkit Listrik Tenaga Surya Terapung Saguling","issuer":"Kementerian Koordinator Bidang Perekonomian","doc_no":"Siaran Pers HM.02.04/140/SET.M.EKON.3/04/2025","date":"2025-04-29","url":"https://www.ekon.go.id/publikasi/detail/6332/implementasi-just-energy-transition-partnership-jetp-melalui-pengembangan-pembangkit-listrik-tenaga-surya-terapung-saguling","accessed":"2026-10-11"},{"title":"Mission Statement: Germany Assumes Co-Lead of Indonesia''s Just Energy Transition Partnership (JETP)","issuer":"Federal Foreign Office (Germany), Embassy Jakarta","date":"2025-02-21","url":"https://jakarta.diplo.de/id-en/jetp-2702134","accessed":"2026-10-11"},{"title":"Perkuat Kerja Sama Strategis Transisi Energi Melalui Skema AZEC, Indonesia dan Jepang Tandatangani Perjanjian Perkembangan PLTP Muara Laboh","issuer":"Kementerian Koordinator Bidang Perekonomian","doc_no":"Siaran Pers HM.02.04/146/SET.M.EKON.3/05/2025","date":"2025-05-05","url":"https://www.ekon.go.id/publikasi/detail/6340/perkuat-kerja-sama-strategis-transisi-energi-melalui-skema-azec-indonesia-dan-jepang-tandatangani-perjanjian-perkembangan-pltp-muara-laboh","accessed":"2026-10-11"}]'::jsonb,
   'verified', false),
  ('ojk_taxonomy-2025q1', '2025Q1', 'ojk_taxonomy', 'advanced',
   'OJK issued version 2 of the Indonesian Taxonomy for Sustainable Finance (TKBI) on 11 February 2025, adding construction and real estate, transport and storage, and forestry and oil palm to the energy sector covered by version 1.',
   'OJK press release SP 29/GKPB/OJK/II/2025 records the issuance at the annual financial-services industry meeting; version 1 was launched at the previous year''s meeting on 20 February 2024. OJK''s FAQ for version 2 (11 February 2025) says use of TKBI is not yet mandatory or binding and carries no sanctions, and that its application in the financial sector will be set later in an OJK regulation.',
   '[{"title":"Penguatan Sektor Jasa Keuangan yang Stabil dan Inklusif untuk Mendukung Program Prioritas Nasional, Pertemuan Tahunan Industri Jasa Keuangan 2025","issuer":"Otoritas Jasa Keuangan","doc_no":"Siaran Pers SP 29/GKPB/OJK/II/2025","date":"2025-02-11","url":"https://ojk.go.id/id/berita-dan-kegiatan/siaran-pers/Pages/Pertemuan-Tahunan-Industri-Jasa-Keuangan-2025.aspx","accessed":"2026-10-11"},{"title":"Sektor Jasa Keuangan yang Kuat dan Stabil untuk Mendukung Pertumbuhan Ekonomi yang Berkelanjutan","issuer":"Otoritas Jasa Keuangan","doc_no":"Siaran Pers SP 19/GKPB/OJK/II/2024","date":"2024-02-20","url":"https://ojk.go.id/id/berita-dan-kegiatan/siaran-pers/Pages/Sektor-Jasa-Keuangan-yang-Kuat-dan-Stabil-untuk-Mendukung-Pertumbuhan-Ekonomi-yang-Berkelanjutan.aspx","accessed":"2026-10-11"},{"title":"Sosialisasi Taksonomi untuk Keuangan Berkelanjutan Indonesia (TKBI) Versi 2","issuer":"Otoritas Jasa Keuangan","date":"2025-05-02","url":"https://keuanganberkelanjutan.ojk.go.id/keuanganberkelanjutan/ArticleList/View/1776","accessed":"2026-10-11"},{"title":"FAQ Taksonomi untuk Keuangan Berkelanjutan Indonesia (TKBI) Versi 2","issuer":"Otoritas Jasa Keuangan","date":"2025-02-11","url":"https://ojk.go.id/id/Publikasi/Roadmap-dan-Pedoman/Sektor-Jasa-Keuangan/Keuangan-Berkelanjutan/Documents/FAQ%20Taksonomi%20untuk%20Keuangan%20Berkelanjutan%20Indonesia%20(TKBI)%20Versi%202.pdf","accessed":"2026-10-11"}]'::jsonb,
   'verified', false),
  ('ojk_taxonomy-2025q2', '2025Q2', 'ojk_taxonomy', 'unchanged',
   'TKBI version 2 remained a non-binding reference in Q2 2025, and OJK held a second round of socialisation on it on 24–25 April 2025.',
   'OJK''s FAQ says the reporting obligation will come through an amendment to POJK 51/POJK.03/2017; OJK''s sustainable-finance hub reported that amendment as a draft in public consultation on 12 February 2026. The next edition, version 3, went to consultation from 11 October to 21 November 2025.',
   '[{"title":"Sosialisasi Taksonomi untuk Keuangan Berkelanjutan Indonesia (TKBI) Versi 2 Tahap 2","issuer":"Otoritas Jasa Keuangan","date":"2025-05-02","url":"https://keuanganberkelanjutan.ojk.go.id/keuanganberkelanjutan/ArticleList/View/1778","accessed":"2026-10-11"},{"title":"FAQ Taksonomi untuk Keuangan Berkelanjutan Indonesia (TKBI) Versi 2","issuer":"Otoritas Jasa Keuangan","date":"2025-02-11","url":"https://ojk.go.id/id/Publikasi/Roadmap-dan-Pedoman/Sektor-Jasa-Keuangan/Keuangan-Berkelanjutan/Documents/FAQ%20Taksonomi%20untuk%20Keuangan%20Berkelanjutan%20Indonesia%20(TKBI)%20Versi%202.pdf","accessed":"2026-10-11"},{"title":"Rancangan Peraturan OJK perubahan atas POJK 51/2017: konsultasi publik","issuer":"Otoritas Jasa Keuangan","date":"2026-02-12","url":"https://keuanganberkelanjutan.ojk.go.id/keuanganberkelanjutan/ArticleList/View/2049","accessed":"2026-10-11"},{"title":"Consultative Paper TKBI Versi 3","issuer":"Otoritas Jasa Keuangan","date":"2025-10-11","url":"https://ojk.go.id/id/regulasi/otoritas-jasa-keuangan/rancangan-regulasi/Pages/Consultative-Paper-TKBI-Versi-3.aspx","accessed":"2026-10-11"}]'::jsonb,
   'verified', false),
  ('danantara-2025q1', '2025Q1', 'danantara', 'unchanged',
   'Law 1/2025 and Government Regulation 10/2025, both dated 24 February 2025, created Danantara with a mandate to increase and optimise the investment and operations of state-owned enterprises; neither text mentions energy, renewables or climate.',
   'Article 3E(3) of the law sets that purpose and Article 3H(1) lets Danantara invest directly or indirectly; Article 2(3) of the regulation repeats the purpose. The President launched Danantara on 24 February 2025. In a speech on 13 February 2025 he said the fund would invest in sectors such as renewable energy, advanced manufacturing, downstream industries and food production; that statement is not part of the legal mandate.',
   '[{"title":"Undang-Undang Nomor 1 Tahun 2025 tentang Perubahan Ketiga atas Undang-Undang Nomor 19 Tahun 2003 tentang Badan Usaha Milik Negara","issuer":"Presiden Republik Indonesia","doc_no":"UU No. 1 Tahun 2025","date":"2025-02-24","url":"https://jdih.setneg.go.id/api/hukumproduk/pdf?l=uploads&f=Salinan%20UU%20Nomor%201%20Tahun%202025.pdf&fl=P20281","accessed":"2026-10-11"},{"title":"Peraturan Pemerintah Nomor 10 Tahun 2025 tentang Organisasi dan Tata Kelola Badan Pengelola Investasi Daya Anagata Nusantara","issuer":"Presiden Republik Indonesia","doc_no":"PP No. 10 Tahun 2025","date":"2025-02-24","url":"https://jdih.setneg.go.id/api/hukumproduk/pdf?l=uploads&f=Salinan%20PP%20Nomor%2010%20Tahun%202025.pdf&fl=P20282","accessed":"2026-10-11"},{"title":"Presiden Prabowo Subianto Luncurkan Danantara, Wujud Komitmen Pengelolaan Investasi Berkelanjutan","issuer":"Kementerian Sekretariat Negara","date":"2025-02-24","url":"https://www.setneg.go.id/baca/index/presiden_prabowo_subianto_luncurkan_danantara_wujud_komitmen_pengelolaan_investasi_berkelanjutan","accessed":"2026-10-11"},{"title":"Speech at World Governments Summit 2025","issuer":"Kementerian Sekretariat Negara","date":"2025-02-13","url":"https://www.setneg.go.id/baca/index/speech_at_world_governments_summit_2025","accessed":"2026-10-11"}]'::jsonb,
   'verified', false),
  ('danantara-2025q2', '2025Q2', 'danantara', 'unchanged',
   'Danantara and the Qatar Investment Authority announced a USD 4 billion joint fund on 15 April 2025 that names renewable energy among its focus sectors.',
   'The release lists downstream industry, healthcare, renewable energy and technology among the sectors the fund will consider. It is a statement of focus by the fund''s managers, not a change to Danantara''s legal mandate.',
   '[{"title":"Danantara Indonesia and Qatar Investment Authority Appointed to Manage USD 4 Billion Joint Investment Fund to Support Indonesia''s Development","issuer":"Danantara Indonesia","date":"2025-04-15","url":"https://www.danantaraindonesia.co.id/media-center/press-releases/danantara-indonesia-and-qatar-investment-authority-appointed-to-manage-usd-4-billion-joint-investment-fund-to-support-indonesias-development","accessed":"2026-10-11"}]'::jsonb,
   'verified', false),
  ('other-2025q1', '2025Q1', 'other', 'advanced',
   'Finance Minister Regulation 5/2025 (signed 7 January, promulgated 21 January 2025) set the procedure for government guarantees of PLN''s payment obligations to independent power producers under renewable power purchase agreements, and of state-company borrowing for renewable generation and grids.',
   'Article 2 provides the guarantees and risk coverage to support renewable generation and the energy transition in the electricity sector. The regulation rests on Article 23(3) of Presidential Regulation 112/2022, which provides for the Finance Minister''s support in the form of fiscal incentives, including financing facilities and guarantees through assigned state-owned enterprises.',
   '[{"title":"Peraturan Menteri Keuangan Nomor 5 Tahun 2025 tentang Tata Cara Pemberian dan Pelaksanaan Penjaminan Pemerintah serta Penanggungan Risiko dalam rangka Percepatan Pengembangan Energi Terbarukan untuk Penyediaan Tenaga Listrik","issuer":"Kementerian Keuangan","doc_no":"PMK No. 5 Tahun 2025","date":"2025-01-07","url":"https://jdih.kemenkeu.go.id/dok/pmk-5-tahun-2025","accessed":"2026-10-11"},{"title":"Peraturan Presiden Nomor 112 Tahun 2022 tentang Percepatan Pengembangan Energi Terbarukan untuk Penyediaan Tenaga Listrik","issuer":"Presiden Republik Indonesia","doc_no":"Perpres No. 112 Tahun 2022","date":"2022-09-13","url":"https://jdih.kemenkeu.go.id/api/download/7332a343-0623-4d26-80f2-9d8f62a5c2ba/2022perpres112.pdf","accessed":"2026-10-11"}]'::jsonb,
   'verified', false),
  ('other-2025q2', '2025Q2', 'other', 'advanced',
   'The World Bank approved a USD 600 million loan to PLN for electricity access in Kalimantan and Sumatra (ISLE-2) on 12 June 2025, a week after Government Regulation 28/2025 (5 June 2025) replaced the risk-based business licensing rules.',
   'The World Bank lists PLN as borrower and the objective as increasing access to sustainable electricity in the Kalimantan and Sumatra regions. PP 28/2025 replaces PP 5/2021; in its energy annex, power generation (KBLI 35111) other than renewable plants integrated with electric-vehicle charging stations is high-risk and needs a business identification number and a licence.',
   '[{"title":"Indonesia Sustainable Least-cost Electrification-2 (ISLE-2) Operation","issuer":"World Bank","doc_no":"Project P501217","date":"2025-06-12","url":"https://projects.worldbank.org/en/projects-operations/project-detail/P501217","accessed":"2026-10-11"},{"title":"Peraturan Pemerintah Nomor 28 Tahun 2025 tentang Penyelenggaraan Perizinan Berusaha Berbasis Risiko","issuer":"Presiden Republik Indonesia","doc_no":"PP No. 28 Tahun 2025","date":"2025-06-05","url":"https://jdih.setneg.go.id/api/hukumproduk/pdf?l=uploads&f=1.%20Salinan%20PP%20Nomor%2028%20Tahun%202025.pdf&fl=P20367","accessed":"2026-10-11"}]'::jsonb,
   'verified', false)
